using AfriWallet.Compliance.Readiness.Models;
namespace AfriWallet.Compliance.Readiness.Checks;
public sealed class RegulatoryClaimCheck:IComplianceReadinessCheck { public string Code=>"CMP-RDY-005";public Task<ReadinessCheck> ExecuteAsync(string root,CancellationToken ct=default){string[] claims=["regulatory certified","regulator approved","aml certified","guaranteed aml compliance"];var hits=new List<string>();foreach(var file in RepositoryCheckUtilities.EnumerateTextFiles(RepositoryCheckUtilities.Resolve(root,"backend","src","Compliance"))){ct.ThrowIfCancellationRequested();var text=File.ReadAllText(file);foreach(var p in claims)if(text.Contains(p,StringComparison.OrdinalIgnoreCase))hits.Add($"{Path.GetFileName(file)}:{p}");}return Task.FromResult(new ReadinessCheck(Code,"Regulatory claim boundary",hits.Count==0?ReadinessStatus.Passed:ReadinessStatus.Failed,hits.Count==0?"No prohibited certification claim detected":string.Join(", ",hits)));} }